    /// <summary>
    /// A LogsConfig object that override the log settings defined in the batch build project. cloudWatchLogs -&gt; (structure) Information about CloudWatch Logs for a build project. Cloud- Watch Logs are enabled by default. status -&gt; (string) [required] The current status of the logs in CloudWatch Logs for a build project. Valid values are: o ENABLED : CloudWatch Logs are enabled for this build project. o DISABLED : CloudWatch Logs are not enabled for this build project. Possible values: o ENABLED o DISABLED groupName -&gt; (string) The group name of the logs in CloudWatch Logs. For more in- formation, see Working with Log Groups and Log Streams . streamName -&gt; (string) The prefix of the stream name of the CloudWatch Logs. For more information, see Working with Log Groups and Log Streams . s3Logs -&gt; (structure) Information about logs built to an S3 bucket for a build project. S3 logs are not enabled by default. status -&gt; (string) [required] The current status of the S3 build logs. Valid values are: o ENABLED : S3 build logs are enabled for this build project. o DISABLED : S3 build logs are not enabled for this build project. Possible values: o ENABLED o DISABLED location -&gt; (string) The ARN of an S3 bucket and the path prefix for S3 logs. If your Amazon S3 bucket name is my-bucket , and your path pre- fix is build-log , then acceptable formats are my-bucket/build-log or arn:aws:s3:::my-bucket/build-log . encryptionDisabled -&gt; (boolean) Set to true if you do not want your S3 build log output en- crypted. By default S3 build logs are encrypted. bucketOwnerAccess -&gt; (string) Specifies the bucket owner's access for objects that another account uploads to their Amazon S3 bucket. By default, only the account that uploads the objects to the bucket has access to these objects. This property allows you to give the bucket owner access to these objects. NOTE: To use this property, your CodeBuild service role must have the s3:PutBucketAcl permission. This permission al- lows CodeBuild to modify the access control list for the bucket. This property can be one of the following values: NONE The bucket owner does not have access to the objects. This is the default. READ_ONLY The bucket owner has read-only access to the objects. The up- loading account retains ownership of the objects. FULL The bucket owner has full access to the objects. Object own- ership is determined by the following criteria: o If the bucket is configured with the Bucket owner preferred setting, the bucket owner owns the objects. The uploading account will have object access as specified by the bucket's policy. o Otherwise, the uploading account retains ownership of the objects. For more information about Amazon S3 object ownership, see Controlling ownership of uploaded objects using S3 Object Ownership in the Amazon Simple Storage Service User Guide . Possible values: o NONE o READ_ONLY o FULL Shorthand Syntax: cloudWatchLogs={status=string,groupName=string,streamName=string},s3Logs={status=string,location=string,encryptionDisabled=boolean,bucketOwnerAccess=string} JSON Syntax: { "cloudWatchLogs": { "status": "ENABLED"|"DISABLED", "groupName": "string", "streamName": "string" }, "s3Logs": { "status": "ENABLED"|"DISABLED", "location": "string", "encryptionDisabled": true|false, "bucketOwnerAccess": "NONE"|"READ_ONLY"|"FULL" } }
    /// </summary>
    [CliOption("--logs-config-override")]
    public string? LogsConfigOverride { get; set; }

